use std::{env, process::ExitCode};
use todolist_rust::{Error, TodoStore};

const HELP: &str = "TODO commands:
  add <description>  Add one task; quote descriptions: add \"Buy milk\"
  delete <id>        Delete a task
  complete <id>      Mark a task complete
  list               List tasks: [ ] incomplete, [x] complete
  help               Show this help (also -h, --help, or no arguments)

Storage: tasks.json in the build-time Cargo project root.
IDs are unsigned decimal integers. Empty descriptions are allowed: add \"\".";

enum Command {
    Add(String),
    Delete(u64),
    Complete(u64),
    List,
    Help,
}

fn parse(args: Vec<String>) -> Result<Command, &'static str> {
    let id = |value: &str| {
        if value.is_empty() || !value.bytes().all(|byte| byte.is_ascii_digit()) {
            return Err("ID must be an unsigned decimal integer");
        }
        value.parse().map_err(|_| "ID is too large for u64")
    };
    match args.as_slice() {
        [] => Ok(Command::Help),
        [command] if matches!(command.as_str(), "help" | "-h" | "--help") => Ok(Command::Help),
        [command] if command == "list" => Ok(Command::List),
        [command, description] if command == "add" => Ok(Command::Add(description.clone())),
        [command, value] if command == "delete" => Ok(Command::Delete(id(value)?)),
        [command, value] if command == "complete" => Ok(Command::Complete(id(value)?)),
        _ => Err("unknown command or incorrect number of arguments"),
    }
}

fn execute(command: Command, store: &TodoStore) -> Result<(), Error> {
    match command {
        Command::Help => println!("{HELP}"),
        Command::Add(description) => println!("Added task {}", store.create(description)?.id),
        Command::Delete(id) => println!("Deleted task {}", store.delete(id)?.id),
        Command::Complete(id) => println!("Completed task {}", store.complete(id)?.id),
        Command::List => {
            let tasks = store.list()?;
            if tasks.is_empty() {
                println!("No tasks.");
            }
            for task in tasks {
                let marker = if task.completed { 'x' } else { ' ' };
                println!("{} [{marker}] {}", task.id, task.description);
            }
        }
    }
    Ok(())
}

fn main() -> ExitCode {
    let command = env::args_os()
        .skip(1)
        .map(|arg| arg.into_string().map_err(|_| "arguments must be UTF-8"))
        .collect::<Result<Vec<_>, _>>()
        .and_then(parse);
    match command {
        Err(error) => {
            eprintln!("{error}. Run 'todolist_rust help' for usage.");
            ExitCode::from(2)
        }
        Ok(command) => match execute(command, &TodoStore::project()) {
            Ok(()) => ExitCode::SUCCESS,
            Err(error) => {
                eprintln!("{error}");
                ExitCode::from(1)
            }
        },
    }
}
"""Public process contract; all files and compilation live in a disposable copy."""
import json
import os
from pathlib import Path
import shutil
import subprocess
import tempfile


def main():
    source = Path(__file__).resolve().parents[1]
    with tempfile.TemporaryDirectory(prefix="todo-cli-") as directory:
        root = Path(directory)
        project = root / "project"
        project.mkdir()
        for filename in ("Cargo.toml", "Cargo.lock"):
            shutil.copy2(source / filename, project / filename)
        shutil.copytree(source / "src", project / "src")
        invocation = root / "invocation"
        invocation.mkdir()
        target = root / "target"
        subprocess.run(
            ["cargo", "build", "--offline", "--manifest-path", str(project / "Cargo.toml"),
             "--target-dir", str(target)], check=True,
        )
        binary = target / "debug" / "todolist_rust"
        storage = project / "tasks.json"
        print("Binary built from disposable project; every launch cwd=invocation", flush=True)

        def run(args, status=0, contains=None):
            result = subprocess.run([os.fsencode(binary), *args], cwd=invocation, capture_output=True)
            stdout, stderr = result.stdout.decode(), result.stderr.decode()
            assert result.returncode == status, (args, result.returncode, stdout, stderr)
            if status == 0:
                assert not stderr, (args, stderr)
                output = stdout
            else:
                assert not stdout, (args, stdout)
                assert stderr.strip(), args
                output = stderr
            if contains is not None:
                assert contains in output, (args, output, contains)
            assert not (invocation / "tasks.json").exists()
            print(f"{args!r}: exit {status}; {output.strip()!r}", flush=True)
            return stdout

        def state(tasks, next_id):
            assert json.loads(storage.read_text()) == {"next_id": next_id, "tasks": tasks}

        def task(identifier, description, completed=False):
            return {"id": identifier, "description": description, "completed": completed}

        def help_forms():
            before = storage.read_bytes() if storage.is_file() else None
            for args in ([], ["help"], ["-h"], ["--help"]):
                output = run(args)
                for phrase in ("add <description>", "delete <id>", "complete <id>",
                               "list", "help", "quote", "tasks.json", "[ ]", "[x]"):
                    assert phrase in output, (args, phrase)
                assert (storage.read_bytes() if storage.is_file() else None) == before

        help_forms()
        assert not storage.exists()
        run(["list"], contains="No tasks")
        run(["add", "Buy milk"], contains="1")
        run(["add", "-urgent"], contains="2")
        a, b = task(1, "Buy milk"), task(2, "-urgent")
        state([a, b], 3)
        assert run(["list"]) == "1 [ ] Buy milk\n2 [ ] -urgent\n"
        run(["complete", "1"], contains="1")
        a = task(1, "Buy milk", True)
        state([a, b], 3)
        assert run(["list"]) == "1 [x] Buy milk\n2 [ ] -urgent\n"
        run(["complete", "1"], contains="1")
        state([a, b], 3)
        assert run(["list"]) == "1 [x] Buy milk\n2 [ ] -urgent\n"
        run(["delete", "2"], contains="2")
        state([a], 3)
        assert run(["list"]) == "1 [x] Buy milk\n"
        run(["delete", "1"], contains="1")
        state([], 3)
        run(["list"], contains="No tasks")
        run(["add", "C"], contains="3")
        run(["add", ""], contains="4")
        run(["add", "  spaced  "], contains="5")
        state([task(3, "C"), task(4, ""), task(5, "  spaced  ")], 6)
        assert run(["list"]) == "3 [ ] C\n4 [ ] \n5 [ ]   spaced  \n"
        help_forms()

        before = storage.read_bytes()
        invalid = [["unknown"], ["--unknown"], ["add"], ["add", "a", "b"],
                   ["list", "extra"], ["help", "extra"], ["-h", "extra"],
                   ["--help", "extra"]]
        for command in ("complete", "delete"):
            invalid.extend([[command], [command, "1", "2"]])
            invalid.extend([[command, value] for value in
                            ("", "-1", "+1", "1a", "1.0", " 1", "١", "18446744073709551616")])
        if os.name == "posix":
            invalid.extend([[b"\xff"], ["add", b"\xff"]])
        for args in invalid:
            run(args, 2, "help")
            assert storage.read_bytes() == before
        for command in ("complete", "delete"):
            for identifier in ("0", "999", "18446744073709551615"):
                run([command, identifier], 1, identifier)
                assert storage.read_bytes() == before
        # Leading zeroes are valid decimal IDs and resolve the same task.
        run(["complete", "0003"], contains="3")
        state([task(3, "C", True), task(4, ""), task(5, "  spaced  ")], 6)

        storage.write_text("{broken JSON")
        before = storage.read_bytes()
        for args in (["list"], ["add", "x"], ["complete", "3"], ["delete", "3"]):
            run(args, 1, "JSON")
            assert storage.read_bytes() == before
        help_forms()
        run(["list", "extra"], 2, "help")
        assert storage.read_bytes() == before
        storage.unlink()
        storage.mkdir()
        for args in (["list"], ["add", "x"], ["complete", "3"], ["delete", "3"]):
            run(args, 1, "directory")
            assert storage.is_dir() and not list(storage.iterdir())
        run(["help"])
    print("PASS: CLI lifecycle, descriptions, help, usage, errors, root path; fixtures cleaned")


