fn persisted_lifecycle_and_identity() -> Result<(), Box<dyn std::error::Error>> {
    let directory = tempfile::tempdir()?;
    let path = directory.path().join("tasks.json");
    let store = TodoStore::at(&path);
    assert!(store.list()?.is_empty());
    let first = store.create("Buy milk")?;
    let second = store.create("Read book")?;
    assert_ne!(first.id, second.id);
    assert_eq!(first.description, "Buy milk");
    assert_eq!(second.description, "Read book");
    assert!(!first.completed && !second.completed);
    assert_eq!(store.list()?, vec![first.clone(), second.clone()]);

    let completed = Task {
        completed: true,
        ..first
    };
    assert_eq!(store.complete(completed.id)?, completed);
    assert_eq!(store.complete(completed.id)?, completed);
    let reloaded = TodoStore::at(&path);
    assert_eq!(reloaded.list()?, vec![completed.clone(), second.clone()]);
    let saved = fs::read(&path)?;
    assert!(matches!(
        reloaded.complete(u64::MAX),
        Err(Error::NotFound(u64::MAX))
    ));
    assert!(matches!(
        reloaded.delete(u64::MAX),
        Err(Error::NotFound(u64::MAX))
    ));
    assert_eq!(fs::read(&path)?, saved);

    assert_eq!(reloaded.delete(second.id)?, second);
    assert_eq!(TodoStore::at(&path).list()?, vec![completed.clone()]);
    let third = TodoStore::at(&path).create("Walk dog")?;
    assert_ne!(third.id, completed.id);
    assert_ne!(third.id, second.id);
    reloaded.delete(third.id)?;
    reloaded.delete(completed.id)?;
    assert!(TodoStore::at(&path).list()?.is_empty());
    Ok(())
}

#[test]
fn corrupt_storage_is_reported_and_preserved() -> Result<(), Box<dyn std::error::Error>> {
    let directory = tempfile::tempdir()?;
    let path = directory.path().join("tasks.json");
    fs::write(&path, b"broken JSON")?;
    let store = TodoStore::at(&path);
    assert!(matches!(store.list(), Err(Error::Json(_))));
    assert!(matches!(
