fn filesystem_failures_do_not_report_success_or_discard_saved_data(
) -> Result<(), Box<dyn std::error::Error>> {
    let directory = tempfile::tempdir()?;
    let path = directory.path().join("tasks.json");
    let saved = TodoStore::at(&path).create("Keep me")?;
    // A regular file cannot be used as a directory, regardless of user privileges.
    assert!(matches!(
        TodoStore::at(path.join("child.json")).list(),
        Err(Error::Io(_))
